void Select(string fieldId)
{
    // 只高亮这一字段在文档里的来源段落，其余字段回到常态
    foreach (var (id, span) in FieldSpans)
    {
        span.Background = id == fieldId ? K.Tint(ArcTokens.Accent, 0.14) : Brushes.Transparent;
    }

    status.Text = $"Showing where {fieldId} came from in the document.";
}

